Voici un programme C++ qui lit un fichier texte ligne par ligne et compte le nombre d'occurrences d'un mot spécifique dans le fichier :

```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string word; // mot à rechercher
    int count = 0; // nombre d'occurrences

    // Demander l'entrée du mot à rechercher
    cout << "Entrez le mot à rechercher : ";
    cin >> word;

    // Ouvrir le fichier pour lecture
    ifstream file("filename.txt");

    if (!file) {
        cerr << "Impossible d'ouvrir le fichier." << endl;
        return 1;
    }

    // Lecture ligne par ligne
    string line;
    while (getline(file, line)) {
        // Convertir la ligne en petit majuscules pour une comparaison case-insensitive
        transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Rechercher le mot dans la ligne
        size_t pos = line.find(word);
        while (pos != string::npos) {
            count++; // Incrémenter le compteur
            pos = line.find(word, pos + 1); // Rechercher le prochain mot dans la ligne
        }
    }

    // Fermer le fichier
    file.close();

    // Afficher le nombre d'occurrences
    cout << "Le mot '" << word << "' apparaît " << count << " fois dans le fichier." << endl;

    return 0;
}
```

